// Using insertion sort because it is faster for small arrays
static void insertion_sort(__uint128_t* arr, int n)
{
    for (int i = 1; i < n; ++i) {
        const __uint128_t key = arr[i];
        int j = i - 1;

        while (j >= 0 && arr[j] > key) {
            arr[j + 1] = arr[j];
            j = j - 1;
        }
        arr[j + 1] = key;
    }
}

typedef void* (*malloc_t)(int size);
typedef void* (*calloc_t)(int count, int size);
typedef void (*free_t)(void* ptr);

/**
 * Function that calculates branchlessly (except for adding to counter) one half of pascal's triangle to figure out
 * which numbers appear more than 3 times. Gets memory manipulation functions as arguments so it can be self-contained.
 * @return First element of a null terminated array.
 */
__uint128_t* search_pascal_multiples_fast(const unsigned char row_limit,
                                          malloc_t my_malloc,
                                          calloc_t my_calloc,
                                          free_t my_free) {
      const unsigned char length = row_limit / 2 + 1;
      __uint128_t* p_row = my_malloc(length * sizeof(__uint128_t));
      unsigned char* counter = my_calloc(MAX_HASH_VALUE + 1, sizeof(unsigned char));
      {
          volatile __uint128_t* vrow = (volatile __uint128_t*)p_row;
          for (unsigned char i = 1; i < length; i++) {
              vrow[i] = 1;
          }
      }
      __uint128_t* result = my_malloc(9 * sizeof(__uint128_t));
      unsigned char p = 0;

      p_row[0] = 3;
      for (unsigned char i = 4; i < row_limit; i++) {
          // Compute even numbered row:
          int h;
          p_row[i / 2 - 1] += p_row[i / 2 - 2];
          for (unsigned char j = i / 2 - 2; j >= 1; j--) {
              p_row[j] += p_row[j - 1];

              h = hash((char*)&p_row[j], sizeof(__uint128_t));
              counter[h] += 2;
              if (counter[h] == 4) {
                  result[p] = p_row[j];
                  p++;
              }
          }
          p_row[0] *= 2;

          h = hash((char*)&p_row[0], sizeof(__uint128_t));
          counter[h] += 1;
          if (counter[h] == 4) {
              result[p] = p_row[0];
              p++;
          }

          // Compute odd numbered row:
          i += 1;
          for (unsigned char j = 0; j < i / 2 - 1; j++) {
              p_row[j] += p_row[j + 1];
              h = hash((char*)&p_row[j], sizeof(__uint128_t));
              counter[h] += 2;
              if (counter[h] == 4) {
                  result[p] = p_row[j];
                  p++;
              }
          }
          p_row[i / 2 - 1] += p_row[i / 2];
      }
      my_free(p_row);
      my_free(counter);
      insertion_sort(result, p);
      result[p] = 0;
      return result;
}
